class Cache
  def initialize(packer: nil)
    @packer = packer
    @storage = {}
  end

  def write(key, payload, stale: false)
    data = {
      payload: payload,
      stale: stale
    }

    if @packer
      stored_value = @packer.dump(data)
    else
      stored_value = data
    end

    @storage[key] = stored_value
  end

  def read(key)
    stored_value = @storage[key]
    return nil if stored_value.nil?

    data = if @packer
             @packer.load(stored_value)
           else
             stored_value
           end

    data[:payload]
  end

  def sweep
    @storage.delete_if do |key, stored_value|
      data = if @packer
               @packer.load(stored_value)
             else
               stored_value
             end
      data[:stale] == true
    end
  end
end
