class Proxy
  def initialize(target)
    @target = target
  end

  def method_missing(method_name, *args, &block)
    if @target.respond_to?(method_name)
      @target.public_send(method_name, *args, &block)
    else
      super
    end
  end

  def respond_to_missing?(method_name, include_private = false)
    @target.respond_to?(method_name, include_private) || super
  end

  def method(symbol, *args)
    if respond_to?(symbol)
      # If it's a method defined on Proxy itself, use that.
      # If it's a method the target responds to, create a proc that calls it via the proxy.
      # The task asks that proxy.method(:name) returns a callable behaving like the proxy call.
      # Using method() on self handles both cases.
      super(symbol, *args)
    else
      raise NameError, "undefined method `#{symbol}' for class `#{self.class}'"
    end
  end
end
